import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import App from './App';

describe("Recipe Card YouTube Button", () => {
  test("shows Watch on YouTube button for valid links and fallback for missing/invalid ones", async () => {
    // Mock recipe with valid YouTube links and some bad links
    const recipes = [
      { strYoutube: "https://www.youtube.com/watch?v=dQw4w9WgXcQ", expectButton: true },
      { strYoutube: "https://youtu.be/i9n8yMi3l3s", expectButton: true },
      { strYoutube: "https://www.youtube.com/embed/U3YFQFvdt2w", expectButton: true },
      { strYoutube: "https://www.youtube.com/v/i9n8yMi3l3s", expectButton: true },
      { strYoutube: "", expectButton: false },
      { strYoutube: "not a youtube url", expectButton: false },
      { strYoutube: "https://www.notyoutube.com/watch?v=abcdefghi12", expectButton: false },
      { strYoutube: "https://www.youtube.com/watch?v=invL1d", expectButton: false },
      { strYoutube: "https://www.youtube.com/watch?v=abcdefghijkl", expectButton: false }, // too long, invalid id
    ];
    for (const rec of recipes) {
      render(
        <div>
          {(() => {
            const fixYoutubeWatchUrl = require('./App').default.prototype?.fixYoutubeWatchUrl;
            const url = fixYoutubeWatchUrl ? fixYoutubeWatchUrl(rec.strYoutube) : "";
            return url ? (
              <a
                href={url}
                target="_blank"
                rel="noopener noreferrer"
                data-testid="youtube-link"
              >
                Watch on YouTube
              </a>
            ) : (
              <span
                style={{
                  color: "#b1aaa7",
                  fontWeight: 500,
                  fontStyle: "italic",
                  background: "#f5ecf8",
                  padding: "1.5px 7px",
                  borderRadius: 7,
                  marginLeft: 2
                }}
                data-testid="no-youtube-link"
              >
                No YouTube video available
              </span>
            );
          })()}
        </div>
      );

      if (rec.expectButton) {
        expect(screen.getByTestId("youtube-link")).toBeInTheDocument();
        const link = screen.getByTestId("youtube-link");
        expect(link).toHaveAttribute("href", expect.stringContaining("youtube.com/watch?v="));
        expect(link).toHaveAttribute("target", "_blank");
        expect(link).toHaveAttribute("rel", "noopener noreferrer");
      } else {
        expect(screen.getByTestId("no-youtube-link")).toBeInTheDocument();
      }
    }
  });
});
